        start=np.clip(center-PATCH//2,0,np.array(target.shape)-PATCH).astype(int)
        p=target[tuple(slice(int(a),int(a)+int(n)) for a,n in zip(start,PATCH))].copy();flips=[]
        for axis in range(3):
