        axes.append((positions>=pad[axis])&(positions<=high[axis]))
        a=pad[axis]-geometry['start'][axis];b=high[axis]-geometry['start'][axis]
        if geometry['flips'][axis]:a,b=n-1-b,n-1-a
        axis_independent.append((local>=a)&(local<=b))
